-- Cambridge International AS & A Level Physics 9702 (2025-2027) verified knowledge seed
-- Source: https://www.cambridgeinternational.org/Images/664565-2025-2027-syllabus.pdf
-- Dataset checksum: 9fe5528df59f72e795dcbd6fb7fe2ff8c

delete from public.curriculum_knowledge where curriculum_version_id='a90d1b2c-4a7e-4122-8509-881ab7561b9e';








update public.curriculum_knowledge k set objective_keys=coalesce((select array_agg(o.id order by o.objective_key) from public.curriculum_objectives o where o.curriculum_version_id=k.curriculum_version_id and o.status='verified' and (o.objective_key = k.topic_key || '.' || coalesce(k.metadata->>'outcomeIndex','') or (k.kind in ('topic','content_scope') and o.objective_key like k.topic_key || '.%'))),'{}') where k.curriculum_version_id='a90d1b2c-4a7e-4122-8509-881ab7561b9e';

) as v(dimension,status,evidence,notes) where not exists (select 1 from public.curriculum_coverage_checks c where c.curriculum_version_id='a90d1b2c-4a7e-4122-8509-881ab7561b9e' and c.dimension=v.dimension);
